pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public { 
        c = new C(address(this));
        owner = c.owner();
    }

    function testFuzz_property(address caller, address recipient) public {
        vm.assume(caller != address(0));
        vm.assume(recipient != address(0));

        uint256 balanceBefore = address(c).balance;
        vm.deal(address(c), 1 ether);

        vm.prank(caller);
        c.withdrawAll(recipient);

        uint256 balanceAfter = address(c).balance;

        // General rule: if caller is the owner, balance becomes zero; otherwise, balance stays at 1 ether
        assertTrue(
            (caller == owner && balanceAfter == 0) ||
            (caller != owner && balanceAfter == 1 ether)
        );
    }
}

