pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public { 
        owner = address(this);
        c = new C(owner); 
    }

    function testFuzz_property(address sender, address recipient, uint256 amount) public {
        // Ensure sender is not the zero address to avoid edge case
        vm.assume(sender != address(0));

        // Fund the contract with some random amount
        vm.deal(address(c), amount);

        // Record balance before
        uint256 balanceBefore = address(c).balance;

        // Perform the call as sender
        vm.prank(sender);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.withdrawAll.selector, recipient));

        // Assert: if the call succeeded (only owner can succeed), balance becomes 0; otherwise unchanged
        assertTrue(success ? (address(c).balance == 0) : (address(c).balance == balanceBefore));
    }
}

