pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, address recipient, uint256 amount) public {
        vm.assume(recipient != address(0));
        vm.assume(sender != address(0));
        vm.deal(sender, amount);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: amount}("");
        vm.assume(success);

        uint256 ownerBalBefore = address(this).balance;
        uint256 contractBalBefore = address(c).balance;

        c.withdrawAll(recipient);

        uint256 ownerBalAfter = address(this).balance;
        uint256 contractBalAfter = address(c).balance;

        assertTrue(ownerBalAfter + contractBalAfter >= ownerBalBefore + contractBalBefore);
    }
}

